477	static void ride_step(void)
478	{
479	    R.seed = R.seed * 1103515245u + 12345u;
480	    R.t += 1.0;
481	    {
482	        const double n = (double)((R.seed >> 16) & 0x7FFF) / 32767.0 - 0.5;
483	        double sp = 22.5 + 5.5 * sin(R.t / 8.0) + 1.6 * n;
484	
485	        if (sp < 8.0) sp = 8.0;
486	        if (sp > 45.0) sp = 45.0;
487	        R.speed = sp;
488	        R.dist_km += sp / 3600.0;
489	        R.hr = 126 + (int)(sp * 1.05) + (int)(3.0 * n);
490	        R.cadence = 78 + (int)(sp * 0.5) + (int)(4.0 * n);
491	        R.elevation = 326 + (int)(9.0 * sin(R.t / 21.0));
492	        if (n > 0.28) {
493	            R.ascent += 1;
494	        }
495	        R.cal = (int)(R.dist_km * 32.0);
496	        if (R.speed > R.max) {
497	            R.max = R.speed;
498	        }
499	        R.avg = (R.elapsed_s > 0)
500	                    ? R.dist_km / ((double)R.elapsed_s / 3600.0)
501	                    : R.speed;
502	    }
503	    {
504	        const double s = R.speed;
505	        const int bin = (s < 15.0) ? 0 : (s < 25.0) ? 1 : (s < 35.0) ? 2
506	                      : (s < 45.0) ? 3 : 4;
507	
508	        R.hist[bin]++;
509	    }
510	}
