663	static void dial_tick_layout(int cx, int cy, int d)
664	{
665	    for (int i = 0; i < 24; i++) {
666	        const int deg = i * 15;
667	        const bool major = (i % 6 == 0);
668	        const double a = (double)deg * DEG2RAD;
669	        const double r1 = (major ? 66.0 : 69.0) * (double)d / 160.0;
670	        const double r2 = 74.0 * (double)d / 160.0;
671	
672	        UD.tick_pts[i][0].x = cx + (int)lround(sin(a) * r1);
673	        UD.tick_pts[i][0].y = cy - (int)lround(cos(a) * r1);
674	        UD.tick_pts[i][1].x = cx + (int)lround(sin(a) * r2);
675	        UD.tick_pts[i][1].y = cy - (int)lround(cos(a) * r2);
676	        if (UD.tick[i] != NULL) {
677	            lv_line_set_points(UD.tick[i], UD.tick_pts[i], 2);
678	        }
679	    }
680	}
