682	static void dial_pointer_layout(int angle)
683	{
684	    const double a = (double)angle * DEG2RAD;
685	    const double sx = sin(a);
686	    const double sy = -cos(a);
687	    const double px = cos(a);
688	    const double py = sin(a);
689	    const double sc = (double)UD.d / 160.0;
690	    const double r0 = 56.0 * sc;
691	    const double r1 = 84.0 * sc;
692	    const int x0 = UD.cx + (int)lround(sx * r0);
693	    const int y0 = UD.cy + (int)lround(sy * r0);
694	    const int x1 = UD.cx + (int)lround(sx * r1);
695	    const int y1 = UD.cy + (int)lround(sy * r1);
696	    const int cw = (int)lround(8.0 * sc);
697	
698	    UD.ptr_pts[0].x = x0;
699	    UD.ptr_pts[0].y = y0;
700	    UD.ptr_pts[1].x = x1;
701	    UD.ptr_pts[1].y = y1;
702	    UD.cross_pts[0].x = x1 - (int)lround(px * cw);
703	    UD.cross_pts[0].y = y1 - (int)lround(py * cw);
704	    UD.cross_pts[1].x = x1 + (int)lround(px * cw);
705	    UD.cross_pts[1].y = y1 + (int)lround(py * cw);
706	    if (UD.ptr != NULL) {
707	        lv_line_set_points(UD.ptr, UD.ptr_pts, 2);
708	    }
709	    if (UD.cross != NULL) {
710	        lv_line_set_points(UD.cross, UD.cross_pts, 2);
711	    }
712	}
