1300	static void elev_build(void)
1301	{
1302	    lv_obj_t *cv;
1303	    const double step = ELEV_VIEW_M / (double)(ELEV_PROF_N - 1);
1304	    double gain = 0;
1305	    double mn;
1306	    double mx;
1307	    int peak = 0;
1308	    char buf[32];
1309	
1310	    d_bg(s_scr, P_PAPER);
1311	    TOP(s_scr, "海拔", "前方 2 km");
1312	    elev_profile_gen();
1313	    mn = s_elev[0];
1314	    mx = s_elev[0];
1315	    for (int i = 0; i + 1 < ELEV_PROF_N; i++) {
1316	        if (s_elev[i + 1] > s_elev[i]) {
1317	            gain += s_elev[i + 1] - s_elev[i];
1318	        }
1319	    }
1320	    for (int i = 1; i < ELEV_PROF_N; i++) {
1321	        if (s_elev[i] < mn) mn = s_elev[i];
1322	        if (s_elev[i] > mx) {
1323	            mx = s_elev[i];
1324	            peak = i;
1325	        }
1326	    }
1327	
1328	    L(s_scr, "海拔 m", PX_MICRO, P_MUTE, 24, 40);
1329	    snprintf(buf, sizeof(buf), "%d–%d m", (int)lround(mn), (int)lround(mx));
1330	    LW(s_scr, buf, PX_MICRO, P_MUTE, 120, 40, 96, LV_TEXT_ALIGN_RIGHT);
1331	
1332	    /* 当前位置竖线 + 大图（190×150）。 */
1333	    (void)B(s_scr, 24, 56, 2, ELEV_BIG_H, P_INK, LV_OPA_COVER, 0);
