1335	    lv_obj_remove_flag(cv, LV_OBJ_FLAG_CLICKABLE);
1336	    lv_obj_remove_flag(cv, LV_OBJ_FLAG_SCROLLABLE);
1337	    lv_obj_set_pos(cv, 26, 56);
1338	    lv_canvas_set_buffer(cv, s_elev_big_cbuf, ELEV_BIG_W, ELEV_BIG_H,
1339	                         LV_COLOR_FORMAT_RGB565);
1340	    lv_obj_set_size(cv, ELEV_BIG_W, ELEV_BIG_H);
1341	    elev_canvas_paint(cv, ELEV_BIG_W, ELEV_BIG_H, true);
1342	
1343	    /* 横轴：0 / 1 km / 2 km。 */
1344	    (void)B(s_scr, 24, 210, 192, 1, P_HAIR, LV_OPA_COVER, 0);
1345	    L(s_scr, "0", PX_MICRO, P_MUTE, 24, 212);
1346	    LW(s_scr, "1 km", PX_MICRO, P_MUTE, 96, 212, 48, LV_TEXT_ALIGN_CENTER);
1347	    LW(s_scr, "2 km", PX_MICRO, P_MUTE, 168, 212, 48, LV_TEXT_ALIGN_RIGHT);
1348	
1349	    snprintf(buf, sizeof(buf), "%.1f", (s_elev[1] - s_elev[0]) / step * 100.0);
1350	    elev_stat(24, "当前坡度", buf, "%");
1351	    snprintf(buf, sizeof(buf), "%d", (int)lround(gain));
1352	    elev_stat(96, "累计爬升", buf, "m");
1353	    snprintf(buf, sizeof(buf), "%d", (int)lround(mx));
1354	    elev_stat(168, "最高点", buf, "m");
1355	    snprintf(buf, sizeof(buf), "最高点在前方 %.1f km",
1356	             (double)peak * step / 1000.0);
1357	    LW(s_scr, buf, PX_MICRO, P_MUTE, 24, 286, 192, LV_TEXT_ALIGN_CENTER);
1358	}
