#!/usr/bin/env bash
# 运行 lvgl_sim 的指定场景（窗口模式；headless 用额外参数透传）。
#
#   ./run.sh                    # 默认 ui：真实自行车 UI，240×320
#   ./run.sh demo               # 控件总览
#   ./run.sh vmap               # vmap 底图 mock
#   ./run.sh ui --scale 3       # 3 倍窗口
#   ./run.sh ui --headless --frames 600 --shot /tmp/ui.png
#   ./run.sh helm               # Helm 码表可交互应用（KEY1/KEY2 = 键盘 1/2）
#   ./run.sh --list             # 列出场景
#   ./run.sh --build ui         # 先构建再跑
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)"
BIN="${HERE}/build/lvgl_sim"

usage() {
    echo "用法: ./run.sh [场景] [额外参数...]"
    echo "  场景: ui（默认，真实 UI）| demo（控件）| vmap（底图 mock）| helm（可交互 Helm）"
    echo "  额外参数原样透传给 lvgl_sim，例如 --scale 3 / --headless --shot out.png"
    echo "  选项: --build（先构建）  --list（列场景）  -h"
}

BUILD=0
if [ "${1:-}" = "--build" ]; then
    BUILD=1
    shift
fi

case "${1:-}" in
    -h|--help) usage; exit 0 ;;
    --list)
        [ -x "${BIN}" ] || { echo "还没构建，先跑 ./build.sh"; exit 1; }
        exec "${BIN}" --list
        ;;
esac

# 第一个参数不以 '-' 开头就当成场景名
SCENE="ui"
if [ $# -gt 0 ] && [ "${1#-}" = "${1}" ]; then
    SCENE="$1"
    shift
fi

if [ "${BUILD}" = "1" ] || [ ! -x "${BIN}" ]; then
    echo "构建中（首次约 1 分钟）…"
    "${HERE}/build.sh"
fi

# 没有桌面时直接跑窗口会报 "cannot open X display"，提前给条明路；
# 但显式要 headless 就不用管 DISPLAY。
HEADLESS=0
for arg in "$@"; do
    case "${arg}" in
        -H|--headless) HEADLESS=1 ;;
    esac
done

if [ "${HEADLESS}" = "0" ] && [ -z "${DISPLAY:-}" ] && [ -z "${WAYLAND_DISPLAY:-}" ]; then
    echo "当前没有图形环境（DISPLAY 为空）。截图模式："
    echo "  ./run.sh ${SCENE} --headless --frames 600 --shot /tmp/${SCENE}.png"
    exit 1
fi

echo "启动场景: ${SCENE}"
exec "${BIN}" --scene "${SCENE}" "$@"
/**
 * @file sim.h
 * @brief LVGL 模拟器公共接口（显示 / 输入 / 截图 / 场景）。
 */

#ifndef SIM_H
#define SIM_H

#include <stdbool.h>
#include <stdint.h>

#include "lvgl.h"

#ifdef __cplusplus
extern "C" {
#endif

typedef struct {
    int width;          /**< 设备像素宽，默认 240 */
    int height;         /**< 设备像素高，默认 320（设备原生竖屏） */
    int scale;          /**< 窗口放大倍数，默认 2 */
    const char *title;  /**< 窗口标题 */
    bool headless;      /**< 不建窗口，跑固定帧数后截图 */
    const char *shot;   /**< headless 下的 PNG 输出路径 */
    int frames;         /**< headless 跑多少帧，默认 30 */
    const char *ui_tour; /**< `ui` 场景巡页截图目录（NULL = 关闭，默认） */
    int tour_frames;    /**< 巡页每页等待帧数，默认 90 */

    /* ── `vmap` 场景（真 vmap 组件）的启动参数 ─────────────────────── */
    int vmap_w;           /**< viewport 宽，0 = 用屏幕宽 */
    int vmap_h;           /**< viewport 高，0 = 用屏幕高 */
    double vmap_lon;      /**< 中心经度；NaN = 用组件默认（板端开机中心） */
    double vmap_lat;      /**< 中心纬度 */
    double vmap_scale;    /**< 连续缩放；<=0 = 组件默认（1.69） */
    int vmap_zoom;        /**< 瓦片层级，0 = 默认 z14 */
    int vmap_icon;        /**< sim_vmap_icon_t */
    int vmap_pan_x;       /**< 首帧后一次性平移量（像素，脚本化拖动取证） */
    int vmap_pan_y;
    bool vmap_pan_set;
    int vmap_rw;          /**< 首帧后运行时改 viewport 宽（0 = 不改） */
    int vmap_rh;          /**< 首帧后运行时改 viewport 高 */
    bool vmap_hud;        /**< 显示 HUD（默认 true） */
    bool vmap_heading;    /**< 航向朝上（R 缓冲旋转显示） */
    double vmap_course;   /**< 航向角（度，正北 0 顺时针）；配合 heading */

    /* 锚点缩放 `vmap_view_zoom_at()`：最多两处，按给定顺序在首帧后执行。 */
    int vmap_zoom_at_n;
    int vmap_za_x[2];
    int vmap_za_y[2];
    double vmap_za_f[2];

    /* 运行时换中心图标（每拍换一次，只调 `set_center_icon()`）：
     * 验证"换图后朝向/旋转逻辑仍在"，不借助 update_arrow。 */
    int vmap_swap_n;
    int vmap_swap_icon[3];

    /* 跟车：喂 N 个向东移动的 GNSS 点（板端热路径 vmap_view_set_center）。 */
    int vmap_follow_n;
    double vmap_follow_m;      /**< 每步东移米数 */

    /* 拖动之后调一次 `center_on()` 回中（验证"可回中 + 不弹回"）。 */
    bool vmap_recenter;

    /* 连续拖动 `vmap_view_pan_px()`：N 步 × (dx,dy)，每步等泵空闲。 */
    int vmap_drag_n;
    int vmap_drag_x;
    int vmap_drag_y;
} sim_cfg_t;

/** @brief `--vmap-icon` 的取值。 */
typedef enum {
    SIM_VMAP_ICON_DEV = 0,  /**< 板端导航箭头（NaviArrow light，默认） */
    SIM_VMAP_ICON_ALT,      /**< 另一枚图标（模拟器运行时画的准星），验证"可换图" */
    SIM_VMAP_ICON_NONE,     /**< 不画中心图标 */
} sim_vmap_icon_t;

