 * 列表放在 240×244 的竖向滚动容器里；焦点移动时 scroll_to_view 把
 * 选中行拉进可视区（项数远多于一屏）。 */

static const char *theme_name(void)
{
    static const char *const n[3] = { "浅色", "深色", "自动" };

    return n[s_theme % 3];
}

static const char *sens_dev(int i)
{
    return s_sens_dev[i][0] != '\0' ? s_sens_dev[i] : "—";
}

static const char *sens_status(int i)
{
    if (s_sens_search == i) {
        return "搜索中";
    }
    return s_sens_on[i] ? "已连接" : "未连接";
}

static const char *route_pref_name(void)
{
    static const char *const n[3] = { "推荐", "最短", "避坡" };

    return n[s_route_pref % 3];
}

static const char *nav_status_name(void)
{
    if (!s_nav_active) {
        return "未导航";
    }
    if (s_nav_phase == 1) {
        return "偏航重规划";
    }
    if (s_nav_phase == 2) {
        return "已到达";
    }
    return "导航中";
}

/* 扫描页附近设备表：每类 3 台（旧 UI 的“扫描列表”语义，数据是假的）。 */
static const char *const SENS_NEARBY[3][3] = {
    { "H808S", "Polar H10", "Garmin HRM" },
    { "Magene S3+", "Wahoo CAD", "iGPSPORT C2" },
    { "Assioma DUO", "Magene P325", "4iiii P3" },
};

static void setl_value_text(const set_item_t *it, char *buf, size_t n)
{
    buf[0] = '\0';
    switch (it->val) {
        case SV_BRIGHT: snprintf(buf, n, "%d%%", s_bright); break;
        case SV_THEME: snprintf(buf, n, "%s", theme_name()); break;
        case SV_LOCK:
            if (s_lock == 0) snprintf(buf, n, "关闭");
            else snprintf(buf, n, "%d 秒", s_lock);
            break;
        case SV_SUN: snprintf(buf, n, "%s", s_sun ? "开" : "关"); break;
        case SV_LANG: snprintf(buf, n, "%s", s_lang ? "English" : "简体中文"); break;
        case SV_DIST_UNIT:
            snprintf(buf, n, "%s", s_unit_mile ? "英里 mile" : "公里 km");
            break;
        case SV_TZ: snprintf(buf, n, "UTC%+d", s_tz); break;
        case SV_H24: snprintf(buf, n, "%s", s_h24 ? "开" : "关"); break;
        case SV_GRADE_UNIT:
            snprintf(buf, n, "%s", s_grade_deg ? "度 °" : "百分号 %");
            break;
        case SV_MAP_UP:
            snprintf(buf, n, "%s", s_map_north ? "北朝上" : "随航向");
            break;
        case SV_REROUTE: snprintf(buf, n, "%s", s_reroute ? "开" : "关"); break;
        case SV_ROUTE_PREF: snprintf(buf, n, "%s", route_pref_name()); break;
        case SV_GRADE_NOW:
            snprintf(buf, n, "%+.1f%s",
                     grade_val(4.2 + (double)s_grade_off_x10 / 10.0),
                     grade_unit());
            break;
        case SV_HR:
        case SV_CAD:
        case SV_PWR: {
            const int i = (it->val == SV_HR) ? 0 : (it->val == SV_CAD) ? 1 : 2;

            snprintf(buf, n, "%s", sens_status(i));
            break;
        }
        case SV_SENS_N: {
            int cnt = 0;

            for (int i = 0; i < 3; i++) {
                if (s_sens_on[i]) cnt++;
            }
            snprintf(buf, n, "已连接 %d / 3", cnt);
            break;
        }
        case SV_PAIR_PHONE:
            if (s_phone_pair_s >= 0) {
                snprintf(buf, n, "配对中 %ds", s_phone_pair_s);
            } else {
                snprintf(buf, n, "2 / 3");
            }
            break;
        case SV_NOTIF: snprintf(buf, n, "%s", s_notif ? "开" : "关"); break;
        case SV_CALLS: snprintf(buf, n, "%s", s_calls_only ? "开" : "关"); break;
        case SV_INBOX_N: snprintf(buf, n, "%d 条", 3); break;
        case SV_REC_N: snprintf(buf, n, "%d 条", s_rec_n); break;
        case SV_EXPORT: snprintf(buf, n, "GPX"); break;
        case SV_SLEEP: snprintf(buf, n, "立即"); break;
        case SV_POWER: snprintf(buf, n, "需确认"); break;
        case SV_USB: snprintf(buf, n, "%s", s_usb_mtp ? "MTP 开" : "关"); break;
        case SV_ABOUT: snprintf(buf, n, "v1.2.6"); break;
        case SV_SCAN_NAME:
            snprintf(buf, n, "%s", sens_dev(s_sens_kind));
            break;
        case SV_SCAN_STATUS:
            snprintf(buf, n, "%s", sens_status(s_sens_kind));
            break;
        case SV_SCAN_DEV: {
            const int d = it->extra % 3;
            bool linked = (s_sens_dev[s_sens_kind][0] != '\0') &&
                          (strcmp(s_sens_dev[s_sens_kind],
                                  SENS_NEARBY[s_sens_kind][d]) == 0);

            if (s_sens_connect_dev == d) {
                snprintf(buf, n, "连接中");
            } else {
                snprintf(buf, n, "%s", linked ? "已连接" : "");
            }
            break;
        }
        case SV_NAV_STATUS:
            snprintf(buf, n, "%s", nav_status_name());
            break;
        case SV_NAV_LEFT: {
            double left = 10.0 - (1.6 + (R.active ? R.dist_km : 0.0));

            if (left < 0.0) left = 0.0;
            snprintf(buf, n, "%.1f %s", conv_dist(left), unit_dist());
            break;
        }
        default:
            if (it->lit != NULL) {
                snprintf(buf, n, "%s", it->lit);
            }
            break;
    }
}

static void setl_style_row(int r, bool on)
{
    lv_obj_set_style_bg_color(SL.chip[r],
                              lv_color_hex(on ? C_DEEP[M_SET] : C_LIGHT[M_SET]),
                              0);
    lv_obj_set_style_text_color(SL.icon[r],
                                lv_color_hex(on ? P_PAPER : P_INK), 0);
    lv_obj_set_style_text_color(SL.name[r],
                                lv_color_hex(on ? P_INK : P_MUTE), 0);
    lv_obj_set_style_text_color(SL.val[r],
                                lv_color_hex(on ? P_INK : P_MUTE), 0);
    lv_obj_set_style_text_color(SL.chev[r],
                                lv_color_hex(on ? C_DEEP[M_SET] : P_MUTE), 0);
    if (SL.bar[r] != NULL) {
        if (on) {
            lv_obj_remove_flag(SL.bar[r], LV_OBJ_FLAG_HIDDEN);
        } else {
            lv_obj_add_flag(SL.bar[r], LV_OBJ_FLAG_HIDDEN);
        }
    }
}

static void setl_focus_apply(bool animated)
{
    (void)animated;
    if (SL.nrow <= 0) {
        return;
    }
    if (SL.sel < 0) SL.sel = 0;
    if (SL.sel >= SL.nrow) SL.sel = SL.nrow - 1;
    for (int r = 0; r < SL.nrow; r++) {
        setl_style_row(r, r == SL.sel);
    }
    if (SL.sel_store != NULL) {
        *SL.sel_store = SL.sel;
    }
    if (SL.row[SL.sel] != NULL) {
        lv_obj_scroll_to_view(SL.row[SL.sel], LV_ANIM_OFF);
    }
}

static void setl_refresh_values(void)
{
    for (int r = 0; r < SL.nrow; r++) {
        const set_item_t *it = &SL.items[SL.item_of_row[r]];
        char buf[32];

        setl_value_text(it, buf, sizeof(buf));
        lv_label_set_text(SL.val[r], buf);
    }
}

static void setl_page_build(const set_item_t *items, int nitems,
                            const char *title, bool back, int *sel,
                            const char *meta_fmt)
{
    int nr = 0;
    char meta[32];

    memset(&SL, 0, sizeof(SL));
    SL.items = items;
    SL.nitems = nitems;
    SL.sel_store = sel;

    d_bg(s_scr, P_PAPER);
    if (back) {
        hfi_create(s_scr, HELM_ICON_BACK, 20, 20, P_MUTE);
        L(s_scr, "设置", PX_SMALL, P_MUTE, 34, 13);
    }
    L(s_scr, title, PX_TITLE, P_INK, 12, 26);
    s_titlebar = B(s_scr, 12, 66, 20, 4, C_DEEP[M_SET], LV_OPA_COVER, 2);

    SL.cont = lv_obj_create(s_scr);
    lv_obj_remove_style_all(SL.cont);
    lv_obj_set_pos(SL.cont, 0, 76);
    lv_obj_set_size(SL.cont, 240, 244);
    lv_obj_set_flex_flow(SL.cont, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_all(SL.cont, 0, 0);
    lv_obj_set_style_pad_row(SL.cont, 0, 0);
    lv_obj_add_flag(SL.cont, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_scroll_dir(SL.cont, LV_DIR_VER);
    lv_obj_set_scrollbar_mode(SL.cont, LV_SCROLLBAR_MODE_OFF);

    for (int i = 0; i < nitems && nr < SETL_MAX; i++) {
        const set_item_t *it = &items[i];

        if (it->group != NULL) {
            lv_obj_t *g = lv_obj_create(SL.cont);

            lv_obj_remove_style_all(g);
            lv_obj_set_size(g, 240, SETL_GROUP_H);
            lv_obj_remove_flag(g, LV_OBJ_FLAG_SCROLLABLE);
            lv_obj_remove_flag(g, LV_OBJ_FLAG_CLICKABLE);
            (void)B(g, 12, 7, 2, 10, C_DEEP[M_SET], LV_OPA_COVER, 1);
            L(g, it->group, PX_MICRO, P_MUTE, 24, 5);
        }

        {
            lv_obj_t *row = lv_obj_create(SL.cont);

            lv_obj_remove_style_all(row);
            lv_obj_set_size(row, 240, SETL_ROW_H);
            lv_obj_remove_flag(row, LV_OBJ_FLAG_SCROLLABLE);
            lv_obj_remove_flag(row, LV_OBJ_FLAG_CLICKABLE);
            SL.row[nr] = row;
            SL.item_of_row[nr] = i;
            SL.row_of_item[i] = nr;
            SL.bar[nr] = B(row, 12, 10, 3, 24, C_DEEP[M_SET],
                           LV_OPA_COVER, 1);
            SL.chip[nr] = CHIP(row, 24, 8, 28, C_LIGHT[M_SET], C_DEEP[M_SET]);
            SL.icon[nr] = hfi_create(SL.chip[nr], it->icon, 14, 14, P_INK);
            SL.name[nr] = L(row, it->name, PX_BODY, P_MUTE, 60, 11);
            SL.val[nr] = LW(row, "", PX_SMALL, P_MUTE, 146, 14, 60,
                            LV_TEXT_ALIGN_RIGHT);
            SL.chev[nr] = hfi_create(row, HELM_ICON_CHEVRON, 214, 22, P_MUTE);
            if (i + 1 < nitems) {
                HAIR(row, 60, SETL_ROW_H - 1, 156);
            }
            nr++;
        }
    }
    SL.nrow = nr;

    if (meta_fmt != NULL) {
        snprintf(meta, sizeof(meta), "%s", meta_fmt);
    } else {
        snprintf(meta, sizeof(meta), "%d 项", nr);
    }
    LW(s_scr, meta, PX_SMALL, P_MUTE, 140, 45, 88, LV_TEXT_ALIGN_RIGHT);

    setl_refresh_values();
    SL.sel = (sel != NULL) ? *sel : 0;
    lv_obj_update_layout(SL.cont);
    setl_focus_apply(false);
}

static void setl_move(int dir)
{
    if (SL.nrow <= 0) {
        return;
    }
    SL.sel = (SL.sel + dir + SL.nrow) % SL.nrow;
    setl_focus_apply(true);
}

