static void sensor_scan_build(void)
{
    static set_item_t items[12];
    int n = 0;

    items[n++] = (set_item_t){ "当前配对", "已配对设备", HELM_ICON_SENSOR,
                               SA_NONE, SV_SCAN_NAME, NULL, s_sens_kind };
    items[n++] = (set_item_t){ NULL, "重新搜索", HELM_ICON_SENSOR,
                               SA_SCAN_SENSOR, SV_SCAN_STATUS, NULL,
                               s_sens_kind };
    items[n++] = (set_item_t){ NULL, "解绑", HELM_ICON_INFO, SA_UNPAIR_SENSOR,
                               SV_NONE, "", s_sens_kind };
    for (int d = 0; d < 3; d++) {
        items[n++] = (set_item_t){ d == 0 ? "附近设备" : NULL,
                                   SENS_NEARBY[s_sens_kind][d], HELM_ICON_SENSOR,
                                   SA_CONNECT_DEV, SV_SCAN_DEV, NULL, d };
    }
    setl_page_build(items, n, "传感器扫描", true, &s_sub_sel,
                    SENS_NEARBY[s_sens_kind][0]);
    /* 标题右上的 meta 用“类型”更有用，覆盖成 心率/踏频/功率。 */
    {
        static const char *const kind[3] = { "心率带", "踏频器", "功率计" };

        lv_obj_t *meta = lv_obj_get_child(s_scr, 3);

        if (meta != NULL) {
            lv_label_set_text(meta, kind[s_sens_kind]);
        }
    }
}

/* 设置动作：短值循环 / 开关 / 进入子页。 */
static void settings_enter(scr_t sub)
{
    s_sub_sel = 0;
    settings_to_sub(sub);
}

static void setl_activate(void)
{
    const set_item_t *it;

    if (SL.sel < 0 || SL.sel >= SL.nrow) {
        return;
    }
    it = &SL.items[SL.item_of_row[SL.sel]];
    switch (it->act) {
        case SA_ENTER_DISPLAY: settings_enter(SCR_DISPLAY); return;
        case SA_ENTER_UNITS: settings_enter(SCR_UNITS); return;
        case SA_ENTER_NAVSET: settings_enter(SCR_NAV_SET); return;
        case SA_ENTER_SENSOR: settings_enter(SCR_SENSOR); return;
        case SA_ENTER_BLUETOOTH: settings_enter(SCR_BLUETOOTH); return;
        case SA_ENTER_RECSET: settings_enter(SCR_REC_SET); return;
        case SA_ENTER_POWER: settings_enter(SCR_POWER); return;
        case SA_ENTER_ABOUT: settings_enter(SCR_ABOUT); return;
        case SA_ENTER_GRADECAL: settings_enter(SCR_GRADECAL); return;
        case SA_ENTER_USB: settings_enter(SCR_USB); return;
        case SA_ENTER_INBOX: settings_enter(SCR_INBOX); return;
        case SA_ENTER_SCAN:
            s_sens_kind = it->extra % 3;
            s_sub_sel = 0;
            settings_to_sub(SCR_SENSOR_SCAN);
            return;
        case SA_CYCLE_BRIGHT:
            s_bright += 10;
            if (s_bright > 100) s_bright = 10;
            toast("亮度已调节");
            break;
        case SA_CYCLE_THEME:
            s_theme = (s_theme + 1) % 3;
            s_dark = (s_theme == 1);
            toast(s_theme == 0 ? "主题：浅色" : s_theme == 1 ? "主题：深色"
                                                             : "主题：自动");
            break;
        case SA_CYCLE_LOCK:
            s_lock = (s_lock == 15) ? 30 : (s_lock == 30) ? 60
                     : (s_lock == 60) ? 0 : 15;
            toast("自动锁定已调整");
            break;
        case SA_TOGGLE_SUN:
            s_sun = !s_sun;
            toast(s_sun ? "阳光增强：开" : "阳光增强：关");
            break;
        case SA_CYCLE_LANG:
            s_lang = (s_lang + 1) % 2;
            toast(s_lang ? "语言：English（占位）" : "语言：简体中文");
            break;
        case SA_CYCLE_UNIT:
            s_unit_mile = !s_unit_mile;
            toast(s_unit_mile ? "距离单位：英里" : "距离单位：公里");
            break;
        case SA_CYCLE_TZ:
            s_tz++;
            if (s_tz > 12) s_tz = -12;
            toast("时区已调整");
            break;
        case SA_TOGGLE_H24:
            s_h24 = !s_h24;
            toast(s_h24 ? "24 小时制：开" : "24 小时制：关");
            break;
        case SA_CYCLE_GRADE_UNIT:
            s_grade_deg = !s_grade_deg;
            toast(s_grade_deg ? "坡度单位：度" : "坡度单位：百分号");
            break;
        case SA_TOGGLE_MAP_UP:
            s_map_north = !s_map_north;
            toast(s_map_north ? "地图：北朝上" : "地图：随航向");
            break;
        case SA_TOGGLE_REROUTE:
            s_reroute = !s_reroute;
            toast(s_reroute ? "偏航重规划：开" : "偏航重规划：关");
            break;
        case SA_CYCLE_ROUTE_PREF:
            s_route_pref = (s_route_pref + 1) % 3;
            toast("路线偏好已调整");
            break;
        case SA_TOGGLE_SOUND:
            s_sound = !s_sound;
            toast(s_sound ? "声音已开启" : "声音已关闭");
            break;
        case SA_PAIR_PHONE:
            s_phone_pair_s = (s_phone_pair_s >= 0) ? -1 : 30;
            toast(s_phone_pair_s >= 0 ? "配对窗口 30 秒" : "已取消配对");
            break;
        case SA_TOGGLE_NOTIF:
            s_notif = !s_notif;
            toast(s_notif ? "通知：开" : "通知：关");
            break;
        case SA_TOGGLE_CALLS:
            s_calls_only = !s_calls_only;
            toast(s_calls_only ? "仅来电：开" : "仅来电：关");
            break;
        case SA_DELETE_RECORDS:
            s_rec_n = 0;
            memset(s_week, 0, sizeof(s_week));
            toast("记录已删除（不可恢复）");
            break;
        case SA_EXPORT_RECORDS:
            toast("正在导出 GPX…");
            break;
        case SA_SLEEP:
            s_idle_return = s_screen;
            s_idle_s = 0;
            s_screen = SCR_IDLE;
            s_busy = false;
            rebuild();
            return;
        case SA_ASK_POWEROFF:
            s_power_mode = 0;
            s_power_phase = 0;
            s_power_ticks = 0;
            s_screen = SCR_SHUTDOWN;
            s_busy = false;
            rebuild();
            return;
        case SA_ASK_REBOOT:
            s_power_mode = 1;
            s_power_phase = 0;
            s_power_ticks = 0;
            s_screen = SCR_SHUTDOWN;
            s_busy = false;
            rebuild();
            return;
        case SA_TOGGLE_USB:
            s_usb_mtp = !s_usb_mtp;
            toast(s_usb_mtp ? "MTP 传输：开" : "MTP 传输：关");
            break;
        case SA_SCAN_SENSOR:
            s_sens_search = s_sens_kind;
            s_sens_ticks = 0;
            s_sens_connect_dev = -1;
            toast("正在搜索…");
            break;
        case SA_UNPAIR_SENSOR:
            s_sens_on[s_sens_kind] = false;
            s_sens_bars[s_sens_kind] = 0;
            snprintf(s_sens_dev[s_sens_kind], sizeof(s_sens_dev[0]), "—");
            toast("已解绑");
            break;
        case SA_CONNECT_DEV:
            s_sens_connect_dev = it->extra % 3;
            s_scan_ticks = 0;
            toast("连接中…");
            break;
        case SA_GRADE_ZERO:
            s_grade_off_x10 = -42;
            toast("坡度已归零");
            break;
        case SA_ROUTE_GPX:
        case SA_ROUTE_POINTS:
        case SA_ROUTE_FAVS:
            nav_start_route(it->act == SA_ROUTE_GPX ? 1
                            : it->act == SA_ROUTE_POINTS ? 2 : 3);
            return;
        case SA_NAV_STOP:
            s_nav_active = false;
            s_nav_phase = 0;
            s_screen = SCR_NAV;
            s_busy = false;
            rebuild();
            toast("导航已停止");
            return;
        case SA_NAV_SKIP:
            s_nav_turn = (s_nav_turn + 1) % 4;
            toast("已跳过本转向");
            break;
        case SA_NAV_NEAREST:
            s_nav_nearest = true;
            s_nav_phase = 0;
            s_nav_ticks = 0;
            toast("已从最近点规划");
            break;
        default:
            return;
    }
    s_idle_s = 0;
    setl_refresh_values();
}
"}

